use super::*;
use crate::pet_runtime::{rules::{RulePolicy,RuleScope,RuleKind,Rule,RuleRevisionMode as Mode,occurrences},store::Store};
use std::{fs,os::unix::fs::PermissionsExt,path::PathBuf};use serde_json::json;
struct F{path:PathBuf,policy:RulePolicy}impl F{
 fn new()->Self{
  let path=std::env::temp_dir().join(format!("coucou-rule-succession-{}",nonce().unwrap()));fs::create_dir(&path).unwrap();fs::set_permissions(&path,fs::Permissions::from_mode(0o700)).unwrap();
  let definition=serde_json::from_value(json!({"name":"Bounded daily","intent":"Prepare one response per authorized occurrence","criteria":["Verify actual result"],"schedule":{"kind":"daily","firstDate":"2026-10-24","days":3,"localTime":"09:00","timeZone":"Europe/Lisbon","weekdays":[1,2,3,4,5,6,7],"overlap":"earlier","gap":"skip"},"missed":"skip","graceSeconds":300,"dataScope":"none","limits":{"maxOccurrences":2,"maxModelCalls":2,"maxToolCalls":0,"maxOutputBytes":8192,"occurrenceOutputBytes":4096,"occurrenceTimeoutSeconds":900}})).unwrap();
  let owner=crate::pet_runtime::model::Owner{pet_id:"ai_ollama".into(),provider:"ollama".into(),adapter:"ollama".into(),model_hint:None};let rule=Rule{id:format!("rule-{}","a".repeat(64)),revision:1,owner,state:crate::pet_runtime::rules::State::Draft,created_at:1000,updated_at:1000,definition};
  let schedule={let _s=crate::pet_calendar::TEST_SERIAL.lock().unwrap();crate::pet_calendar::schedule::resolve(&rule.definition.schedule,||true).unwrap()};let first=schedule.slots[0].at.unwrap();let last=schedule.slots.last().unwrap().at.unwrap();
  let policy=RulePolicy{dispatch:None,schema_version:1,scope:RuleScope::BoundedRuleRecurrenceWithoutSelectedData,rule,payment:crate::pet_runtime::admission::Payment::LocalOnly,destination:crate::pet_memory::context_model::Destination::Server{provider:"ollama".into(),endpoint:"http://127.0.0.1:11434/v1/chat/completions".into(),model:"fixture-free".into()},model:"fixture-free".into(),engine_binding:None,policy_revision:"b".repeat(64),descriptor_semantics:"c".repeat(64),schedule,prepared_at:first-60_000,valid_until:last+900_000};assert!(policy.valid());Self{path,policy}
 }
 fn root(&self)->PathBuf{self.path.join("consent")}
 fn authority(&self)->Authority{Authority::ensure(&self.root()).unwrap()}
 fn candidate(&self)->RuleGrant{RuleGrant{schema_version:1,kind:RuleKind::RuleRecurrence,decision_id:nonce().unwrap(),revision:nonce().unwrap(),policy:self.policy.clone(),phase:RulePhase::Active,approved_at:self.policy.prepared_at,updated_at:self.policy.prepared_at,revoked_at:None,reservations:vec![],intent_retirements:vec![],succession:None,revision_authority:None}}
 fn at(&self,i:usize)->u64{self.policy.schedule.slots[i].at.unwrap()}
 fn bytes(&self,g:&RuleGrant)->Vec<u8>{fs::read(self.root().join(format!("{}.json",g.decision_id))).unwrap()}
}impl Drop for F{fn drop(&mut self){let _=fs::remove_dir_all(&self.path);}}


fn base(f:&F,a:&Authority)->RuleGrant{let g=f.candidate();a.issue_rule(&g,g.approved_at,||true).unwrap();a.reserve_rule_occurrence(&g.decision_id,&f.policy.hash().unwrap(),0,f.at(0),||true).unwrap();a.revoke_rule("ai_ollama",&f.policy.rule.id,&g.decision_id,f.at(0)+1).unwrap();g}
fn changed(f:&F,now:u64)->RulePolicy{let mut p=f.policy.clone();p.rule.revision+=1;p.rule.updated_at=now;p.rule.definition.name="Reviewed revision".into();p.rule.definition.intent="Revised future response".into();p.prepared_at=now;assert!(p.valid());p}
fn revise(a:&Authority,p:&RulePolicy,mode:Mode,at:u64)->RuleGrant{let s=a.prepare_rule_revision(p,mode,at).unwrap();let c=s.candidate(&nonce().unwrap(),at).unwrap();assert_eq!(c.schema_version,7);a.succeed_rule(&s,&c,at+1,||true).unwrap()}
fn stop(a:&Authority,g:&RuleGrant,at:u64){a.revoke_rule(&g.policy.rule.owner.pet_id,&g.policy.rule.id,&g.decision_id,at).unwrap();}
fn evidence(g:&crate::pet_runtime::model::Record,p:&RulePolicy,n:u64)->crate::pet_runtime::admission::Evidence{let mut d=crate::pet_runtime::admission_tests::descriptor(g,n);d.binding.model=Some(p.model.clone());d.capabilities[0].model_binding=Some(p.model.clone());crate::pet_runtime::admission::Evidence::observe(g,&d,p.policy_revision.clone(),n,false,false).unwrap()}
#[test]fn rule_revision_core_carry_keeps_original_spend_and_new_policy_future_boundary(){
 let f=F::new();let a=f.authority();let root=base(&f,&a);let mut p=changed(&f,f.at(0)+2);p.model="explicit-other-model".into();if let crate::pet_memory::context_model::Destination::Server{model,endpoint,..}=&mut p.destination{*model=p.model.clone();*endpoint="http://127.0.0.1:12345/v1/chat/completions".into();}assert!(p.valid());let g=revise(&a,&p,Mode::CarryRemaining,f.at(0)+3);let bounds=a.rule_execution_bounds(&g.decision_id).unwrap();assert_eq!(bounds.prior.len(),1);assert_eq!(bounds.future_after,f.at(0)+3);assert_eq!(a.rule_status(&p.rule,true).unwrap().remaining_occurrences,Some(1));assert!(a.reserve_rule_occurrence(&g.decision_id,&p.hash().unwrap(),0,f.at(0)+4,||true).is_err());
 Store::ensure(&f.path.join("goals")).unwrap();let store=Store::existing_verified(&f.path.join("goals"),&f.root()).unwrap().unwrap();let main=crate::chat::Chat::persistent(f.path.join("manual.json"));let child=occurrences::admit_at(&store,&a,&f.path.join("contexts"),&main,&g.decision_id,1,||f.at(1),|_|true,|r,n|Ok(evidence(r,&p,n))).unwrap();let queued=store.read(&child.goal_id,"ai_ollama").unwrap();a.verify_queued(&queued,f.at(1)+1).unwrap();assert_eq!(queued.admissions[0].spec.resolved_model,p.model);let status=a.rule_status(&p.rule,true).unwrap();assert_eq!(status.committed_occurrences,2);assert_eq!(status.remaining_occurrences,Some(0));assert_eq!(a.rule_grant(&root.decision_id).unwrap().phase,RulePhase::Revoked);assert!(a.reserve_rule_occurrence(&g.decision_id,&p.hash().unwrap(),2,f.at(2),||true).is_err());
 stop(&a,&g,f.at(1)+2);let mut renewed=p.clone();renewed.prepared_at=f.at(1)+3;let fresh=revise(&a,&renewed,Mode::RenewFiniteAllocation,f.at(1)+3);assert!(a.verify_queued(&queued,f.at(1)+4).is_err());assert!(a.rule_execution_bounds(&fresh.decision_id).unwrap().prior.is_empty());assert_eq!(a.rule_status(&p.rule,true).unwrap().remaining_occurrences,Some(2));a.reserve_rule_occurrence(&fresh.decision_id,&renewed.hash().unwrap(),2,f.at(2),||true).unwrap();let status=a.rule_status(&p.rule,true).unwrap();assert_eq!(status.committed_occurrences,3);assert_eq!(status.remaining_occurrences,Some(1));let allocation=status.lineage.unwrap().allocation.unwrap();assert_eq!(allocation.root_decision_id,fresh.decision_id);assert_eq!(allocation.committed_occurrences,1);assert_eq!(allocation.cumulative_committed_occurrences,3);
 stop(&a,&fresh,f.at(2)+1);let s=a.prepare_rule_succession("ai_ollama",&p.rule.id,f.at(2)+2).unwrap();let continued=s.candidate(&nonce().unwrap(),f.at(2)+2).unwrap();a.succeed_rule(&s,&continued,f.at(2)+3,||true).unwrap();assert_eq!(a.rule_prior_allocations(&continued.decision_id).unwrap().len(),1);assert_eq!(a.rule_status(&p.rule,true).unwrap().remaining_occurrences,Some(1));
}
#[test]fn rule_revision_core_pending_new_allocation_requires_own_mode_and_original_choice(){
 for fault in [Fault::BeforeGrantPublish,Fault::AfterGrantPublish]{let f=F::new();let mut a=f.authority();let root=base(&f,&a);let p=changed(&f,f.at(0)+2);let s=a.prepare_rule_revision(&p,Mode::RenewFiniteAllocation,f.at(0)+3).unwrap();let c=s.candidate(&nonce().unwrap(),f.at(0)+3).unwrap();assert_eq!(s.revision_preview()["oldUnusedOccurrencesRetired"],1);a.fault=fault;assert!(a.succeed_rule(&s,&c,f.at(0)+4,||true).is_err());drop(a);let a=Authority::existing(&f.root()).unwrap();if !f.root().join(format!("{}.json",c.decision_id)).exists(){assert!(a.prepare_rule_succession("ai_ollama",&p.rule.id,f.at(0)+5).is_err());assert!(a.prepare_rule_revision(&p,Mode::CarryRemaining,f.at(0)+5).is_err());let mut requested=p.clone();requested.prepared_at=f.at(0)+5;let old=a.prepare_rule_revision(&requested,Mode::RenewFiniteAllocation,f.at(0)+5).unwrap();assert_eq!(old.candidate(&nonce().unwrap(),f.at(0)+5).unwrap(),c);a.succeed_rule(&old,&c,f.at(0)+6,||true).unwrap();}else{a.succeed_rule(&s,&c,f.at(0)+6,||true).unwrap();}assert_eq!(a.rule_status(&p.rule,true).unwrap().remaining_occurrences,Some(2));assert_eq!(a.rule_status(&p.rule,true).unwrap().committed_occurrences,1);assert_eq!(a.rule_grant(&root.decision_id).unwrap().phase,RulePhase::Revoked);}
}
#[test]fn rule_revision_core_carry_cannot_change_limits_or_extend_time_and_renewal_can_be_explicit(){
 let f=F::new();let a=f.authority();base(&f,&a);let mut p=changed(&f,f.at(0)+2);p.rule.definition.limits.max_occurrences=3;p.rule.definition.limits.max_model_calls=3;p.rule.definition.limits.max_output_bytes=12288;assert!(p.valid());assert!(a.prepare_rule_revision(&p,Mode::CarryRemaining,f.at(0)+3).is_err());assert!(a.prepare_rule_revision(&p,Mode::RenewFiniteAllocation,f.at(0)+3).is_ok());
 let mut p=changed(&f,f.at(0)+2);p.prepared_at=f.policy.valid_until+1;p.rule.updated_at=p.prepared_at;p.rule.definition.schedule.days=10;{let _guard=crate::pet_calendar::TEST_SERIAL.lock().unwrap();p.schedule=crate::pet_calendar::schedule::resolve(&p.rule.definition.schedule,||true).unwrap();}p.valid_until=p.schedule.slots.last().unwrap().at.unwrap()+900000;assert!(p.valid());assert!(a.prepare_rule_revision(&p,Mode::CarryRemaining,p.prepared_at).is_err());assert!(a.prepare_rule_succession("ai_ollama",&p.rule.id,p.prepared_at).is_err());let s=a.prepare_rule_revision(&p,Mode::RenewFiniteAllocation,p.prepared_at).unwrap();let c=s.candidate(&nonce().unwrap(),p.prepared_at).unwrap();let mut forged=c.clone();forged.revision_authority.as_mut().unwrap().mode=Mode::CarryRemaining;assert!(a.succeed_rule(&s,&forged,p.prepared_at+1,||true).is_err());assert!(a.succeed_rule(&s,&c,p.prepared_at+1,||false).is_err());a.succeed_rule(&s,&c,p.prepared_at+1,||true).unwrap();assert_eq!(a.rule_status(&p.rule,true).unwrap().remaining_occurrences,Some(2));
}
#[test]fn rule_revision_core_old_formats_and_restored_history_stay_data_only(){
 let f=F::new();let a=f.authority();let root=base(&f,&a);let original=a.rule_grant(&root.decision_id).unwrap();assert!(serde_json::to_value(&original).unwrap().get("revisionAuthority").is_none());let p=changed(&f,f.at(0)+2);let g=revise(&a,&p,Mode::RenewFiniteAllocation,f.at(0)+3);let before=f.bytes(&g);let review=restoration::Review::capture(&f.root(),&f.path.join("goals"),&"d".repeat(64),||Ok(())).unwrap();let fp=review.fingerprint().unwrap();review.apply(&fp,||Ok(())).unwrap();let a=Authority::existing(&f.root()).unwrap();let status=a.rule_status(&p.rule,true).unwrap();assert!(status.snapshot_only);assert_eq!(status.remaining_occurrences,None);assert!(a.prepare_rule_revision(&p,Mode::RenewFiniteAllocation,f.at(0)+4).is_err());assert!(a.reserve_rule_occurrence(&g.decision_id,&p.hash().unwrap(),1,f.at(1),||true).is_err());assert_eq!(f.bytes(&g),before);
}
